INSERT INTO grammar (id, pattern, meaning, connection, jlpt_level, conversation_level, is_core) VALUES ('a1220848-8fa0-4c55-8fd2-320e23b7b810', 'いいね', '좋네', '会話[かいわ]リアクション', 4, 5, FALSE);
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('a1220848-8fa0-4c55-8fd2-320e23b7b810', 'それ、いいね。', '그거 좋네.', 'That''s nice.');
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('a1220848-8fa0-4c55-8fd2-320e23b7b810', 'いいね、やってみよう。', '좋다, 해보자.', 'Sounds good, let''s try.');
INSERT INTO grammar (id, pattern, meaning, connection, jlpt_level, conversation_level, is_core) VALUES ('446d26cf-8bd2-4cb6-9bd5-a961863cb63b', 'じゃあ', '그럼 (전환/정리)', '会話[かいわ]つなぎ', 4, 5, FALSE);
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('446d26cf-8bd2-4cb6-9bd5-a961863cb63b', 'じゃあ、また連絡[れんらく]する。', '그럼 다시 연락할게.', 'Alright then, I''ll message you.');
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('446d26cf-8bd2-4cb6-9bd5-a961863cb63b', 'じゃあ、それで行[い]こう。', '그럼 그걸로 하자.', 'Okay, let''s go with that.');
INSERT INTO grammar (id, pattern, meaning, connection, jlpt_level, conversation_level, is_core) VALUES ('70cc630c-1489-4c8d-bcc2-2bb6757c2e31', 'そういうことか', '아, 그런 거구나', '会話[かいわ]リアクション', 4, 4, FALSE);
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('70cc630c-1489-4c8d-bcc2-2bb6757c2e31', 'ああ、そういうことか。', '아, 그런 거구나.', 'Ah, I see.');
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('70cc630c-1489-4c8d-bcc2-2bb6757c2e31', 'そういうことか。納得[なっとく]した。', '그런 거였구나. 납득했어.', 'That makes sense now.');
INSERT INTO grammar (id, pattern, meaning, connection, jlpt_level, conversation_level, is_core) VALUES ('68c499f9-d271-43a3-8174-1137126e7e2a', 'そうなんだ', '아 그렇구나 (리액션)', '会話[かいわ]リアクション', 4, 5, FALSE);
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('68c499f9-d271-43a3-8174-1137126e7e2a', 'そうなんだ。知[し]らなかった。', '아 그렇구나. 몰랐어.', 'Oh, really. I didn''t know.');
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('68c499f9-d271-43a3-8174-1137126e7e2a', 'そうなんだ。じゃあ、また今度[こんど]ね。', '그렇구나. 그럼 다음에 보자.', 'I see. Then, maybe next time.');
INSERT INTO grammar (id, pattern, meaning, connection, jlpt_level, conversation_level, is_core) VALUES ('55e14064-41c0-4a03-87b6-279bfe4e99da', 'そっか', '아 그렇구나 (가벼움)', '会話[かいわ]リアクション', 4, 4, FALSE);
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('55e14064-41c0-4a03-87b6-279bfe4e99da', 'そっか、分[わ]かった。', '아 그렇구나, 알겠어.', 'I see, okay.');
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('55e14064-41c0-4a03-87b6-279bfe4e99da', 'そっか。じゃあ後[あと]で。', '아 그렇구나. 그럼 나중에.', 'I see. Then later.');
INSERT INTO grammar (id, pattern, meaning, connection, jlpt_level, conversation_level, is_core) VALUES ('1bb473f1-f2e9-4163-9be4-255e366bfb7e', 'それって？', '그게 뭐야? / 그건?', '会話[かいわ]で聞[き]き返[かえ]し', 4, 5, TRUE);
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('1bb473f1-f2e9-4163-9be4-255e366bfb7e', 'それって何[なに]？', '그게 뭐야?', 'What''s that?');
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('1bb473f1-f2e9-4163-9be4-255e366bfb7e', 'それって本当[ほんとう]？', '그거 진짜야?', 'Is that true?');
INSERT INTO grammar (id, pattern, meaning, connection, jlpt_level, conversation_level, is_core) VALUES ('844872f5-3285-4920-9112-d40c68914787', 'それで？', '그래서?', '会話[かいわ]つなぎ', 4, 5, FALSE);
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('844872f5-3285-4920-9112-d40c68914787', 'それで？続[つづ]きは？', '그래서? 다음은?', 'And then? What happened next?');
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('844872f5-3285-4920-9112-d40c68914787', 'それで、どうしたの？', '그래서, 어떻게 됐어?', 'So, what did you do?');
INSERT INTO grammar (id, pattern, meaning, connection, jlpt_level, conversation_level, is_core) VALUES ('e898ebb6-ff8f-443f-bd6f-ce20ce18781d', 'つまり', '즉, 요약하면', '文[ぶん]まとめ', 4, 4, FALSE);
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('e898ebb6-ff8f-443f-bd6f-ce20ce18781d', 'つまり、今[いま]は無理[むり]ってこと？', '즉, 지금은 무리라는 거야?', 'So basically, it''s not possible now?');
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('e898ebb6-ff8f-443f-bd6f-ce20ce18781d', 'つまり、来週[らいしゅう]にする。', '즉, 다음 주로 하자.', 'In short, let''s do it next week.');
INSERT INTO grammar (id, pattern, meaning, connection, jlpt_level, conversation_level, is_core) VALUES ('51cd60a3-f990-47fc-8ab0-0d8fade851e1', 'ということは', '~라는 건… (조금 더 정중)', '文[ぶん] + ということは', 4, 4, FALSE);
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('51cd60a3-f990-47fc-8ab0-0d8fade851e1', 'ということは、明日[あした]も忙[いそが]しいんだね。', '그럼 내일도 바쁜 거네.', 'So that means you''re busy tomorrow too.');
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('51cd60a3-f990-47fc-8ab0-0d8fade851e1', 'ということは、私[わたし]がやればいい？', '그럼 내가 하면 돼?', 'So, should I do it?');
INSERT INTO grammar (id, pattern, meaning, connection, jlpt_level, conversation_level, is_core) VALUES ('0ad57258-f655-460f-9811-4c9c2a056e59', 'どういう意味[いみ]？', '무슨 뜻이야?', '会話[かいわ]で確認[かくにん]', 4, 5, TRUE);
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('0ad57258-f655-460f-9811-4c9c2a056e59', 'どういう意味[いみ]？もう一回[いっかい]言[い]って。', '무슨 뜻이야? 한 번 더 말해줘.', 'What do you mean? Say it again.');
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('0ad57258-f655-460f-9811-4c9c2a056e59', 'それ、どういう意味[いみ]で言[い]ったの？', '그거 무슨 뜻으로 말한 거야?', 'What did you mean by that?');
INSERT INTO grammar (id, pattern, meaning, connection, jlpt_level, conversation_level, is_core) VALUES ('7f8155f9-be95-47a2-ba03-4f82e62d8d65', 'どっちがいい？', '어느 쪽이 좋아?', '会話[かいわ]で選択[せんたく]', 4, 5, FALSE);
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('7f8155f9-be95-47a2-ba03-4f82e62d8d65', '土曜[どよう]と日曜[にちよう]、どっちがいい？', '토요일이랑 일요일, 어느 쪽이 좋아?', 'Saturday or Sunday, which is better?');
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('7f8155f9-be95-47a2-ba03-4f82e62d8d65', 'これとそれ、どっちがいい？', '이거랑 그거, 어느 게 좋아?', 'This or that, which do you want?');
INSERT INTO grammar (id, pattern, meaning, connection, jlpt_level, conversation_level, is_core) VALUES ('f5361b54-7eff-49a6-be48-e7860945b4b4', 'なるほど', '그렇군요 / 이해했어요', '会話[かいわ]リアクション', 4, 5, FALSE);
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('f5361b54-7eff-49a6-be48-e7860945b4b4', 'なるほど、そういうことね。', '그렇군, 그런 거구나.', 'I see, that''s what it is.');
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('f5361b54-7eff-49a6-be48-e7860945b4b4', 'なるほど。じゃあ、そうしよう。', '알겠어. 그럼 그렇게 하자.', 'Got it. Let''s do that.');
INSERT INTO grammar (id, pattern, meaning, connection, jlpt_level, conversation_level, is_core) VALUES ('159381bd-bad9-4a4a-ad68-1c8831de3b0d', 'なんで？', '왜?', '会話[かいわ]で理由[りゆう]を聞[き]く', 4, 5, TRUE);
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('159381bd-bad9-4a4a-ad68-1c8831de3b0d', 'なんで行[い]かないの？', '왜 안 가?', 'Why aren''t you going?');
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('159381bd-bad9-4a4a-ad68-1c8831de3b0d', 'なんでそんなに急[いそ]ぐの？', '왜 그렇게 급해?', 'Why are you in such a hurry?');
INSERT INTO grammar (id, pattern, meaning, connection, jlpt_level, conversation_level, is_core) VALUES ('1a729e70-bf36-4299-b675-8d92f66b76bf', 'へえ', '오~', '会話[かいわ]リアクション', 4, 4, FALSE);
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('1a729e70-bf36-4299-b675-8d92f66b76bf', 'へえ、面白[おもしろ]いね。', '오, 재미있네.', 'Oh, interesting.');
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('1a729e70-bf36-4299-b675-8d92f66b76bf', 'へえ、そんなことがあるんだ。', '오, 그런 일이 있구나.', 'Wow, that happens.');
INSERT INTO grammar (id, pattern, meaning, connection, jlpt_level, conversation_level, is_core) VALUES ('c7af24de-7b49-4961-aafa-4ee87b539a83', 'まじで？', '진짜?', '会話[かいわ]リアクション', 4, 5, FALSE);
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('c7af24de-7b49-4961-aafa-4ee87b539a83', 'まじで？本当[ほんとう]？', '진짜? 정말?', 'Seriously? For real?');
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('c7af24de-7b49-4961-aafa-4ee87b539a83', 'まじで？それはすごい。', '진짜? 그거 대단하네.', 'No way? That''s amazing.');
INSERT INTO grammar (id, pattern, meaning, connection, jlpt_level, conversation_level, is_core) VALUES ('f5c45299-a5eb-4990-b3cf-858ce540a0d7', 'もう一回[いっかい]', '한 번 더', '会話[かいわ]でお願い', 4, 5, FALSE);
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('f5c45299-a5eb-4990-b3cf-858ce540a0d7', 'もう一回[いっかい]言[い]って。', '한 번 더 말해줘.', 'Say it one more time.');
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('f5c45299-a5eb-4990-b3cf-858ce540a0d7', 'もう一回[いっかい]送[おく]ってくれる？', '한 번 더 보내줄래?', 'Can you send it again?');
INSERT INTO grammar (id, pattern, meaning, connection, jlpt_level, conversation_level, is_core) VALUES ('1cd39775-d0cc-403f-a101-60b114282526', 'もし～なら', '만약 ~라면', 'もし + 文[ぶん] + なら', 4, 5, TRUE);
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('1cd39775-d0cc-403f-a101-60b114282526', 'もし時間[じかん]があるなら会[あ]おう。', '만약 시간 있으면 만나자.', 'If you have time, let''s meet.');
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('1cd39775-d0cc-403f-a101-60b114282526', 'もし無理[むり]なら大丈夫[だいじょうぶ]。', '무리면 괜찮아.', 'If it''s not possible, it''s okay.');
INSERT INTO grammar (id, pattern, meaning, connection, jlpt_level, conversation_level, is_core) VALUES ('d761e9e9-436e-4c47-a495-1c3755006c7b', 'よかった', '다행이다', '会話[かいわ]リアクション', 4, 5, FALSE);
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('d761e9e9-436e-4c47-a495-1c3755006c7b', 'よかった。安心[あんしん]した。', '다행이다. 안심했어.', 'Good. I''m relieved.');
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('d761e9e9-436e-4c47-a495-1c3755006c7b', '間[ま]に合[あ]ってよかったね。', '시간 맞춰서 다행이다.', 'Good thing you made it in time.');
INSERT INTO grammar (id, pattern, meaning, connection, jlpt_level, conversation_level, is_core) VALUES ('04c9d6d4-a3f4-4704-88a0-4b26a496e574', 'わかった', '알겠어', '会話[かいわ]リアクション', 4, 5, TRUE);
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('04c9d6d4-a3f4-4704-88a0-4b26a496e574', 'わかった、任[まか]せて。', '알겠어, 맡겨.', 'Got it, leave it to me.');
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('04c9d6d4-a3f4-4704-88a0-4b26a496e574', 'わかったよ。', '알겠어.', 'Okay.');
INSERT INTO grammar (id, pattern, meaning, connection, jlpt_level, conversation_level, is_core) VALUES ('27b3f234-66c5-428b-9b49-c972b60ea093', '大変[たいへん]だね', '힘들겠다', '会話[かいわ]リアクション', 4, 5, FALSE);
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('27b3f234-66c5-428b-9b49-c972b60ea093', 'それは大変[たいへん]だね。', '그건 힘들겠다.', 'That sounds hard.');
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('27b3f234-66c5-428b-9b49-c972b60ea093', '毎日[まいにち]は大変[たいへん]だね。', '매일은 힘들겠다.', 'That must be tough every day.');
INSERT INTO grammar (id, pattern, meaning, connection, jlpt_level, conversation_level, is_core) VALUES ('392c7ccd-eebd-4303-8696-f01866b21979', '本当[ほんとう]に？', '진짜로?', '会話[かいわ]リアクション', 4, 5, TRUE);
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('392c7ccd-eebd-4303-8696-f01866b21979', '本当[ほんとう]に？信[しん]じられない。', '진짜야? 믿기 힘들어.', 'Really? I can''t believe it.');
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('392c7ccd-eebd-4303-8696-f01866b21979', '本当[ほんとう]に？すごいね。', '진짜야? 대단하네.', 'Really? That''s amazing.');
INSERT INTO grammar (id, pattern, meaning, connection, jlpt_level, conversation_level, is_core) VALUES ('ef6a63af-38bf-49c5-9dd6-47d42f2c5262', '～いくら', '얼마', 'いくら', 5, 5, FALSE);
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('ef6a63af-38bf-49c5-9dd6-47d42f2c5262', 'これ、いくらですか？', '이거 얼마예요?', 'How much is this?');
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('ef6a63af-38bf-49c5-9dd6-47d42f2c5262', '全部[ぜんぶ]でいくらですか？', '전부 얼마예요?', 'How much is it in total?');
INSERT INTO grammar (id, pattern, meaning, connection, jlpt_level, conversation_level, is_core) VALUES ('671f3693-b7d4-4afd-841f-adb82e9a51bd', '～おかげで', '~덕분에', '名詞[めいし]/文[ぶん] + おかげで', 4, 5, FALSE);
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('671f3693-b7d4-4afd-841f-adb82e9a51bd', '君[きみ]のおかげで助[たす]かった。', '네 덕분에 살았어.', 'Thanks to you, it helped.');
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('671f3693-b7d4-4afd-841f-adb82e9a51bd', '天気[てんき]のおかげで楽[たの]しかった。', '날씨 덕분에 즐거웠어.', 'Thanks to the weather, it was fun.');
INSERT INTO grammar (id, pattern, meaning, connection, jlpt_level, conversation_level, is_core) VALUES ('a5e76559-5c06-4604-9949-75990d8a8a89', '～かな', '~일까?', '文[ぶん] + かな', 4, 5, TRUE);
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('a5e76559-5c06-4604-9949-75990d8a8a89', '大丈夫[だいじょうぶ]かな。', '괜찮을까.', 'I wonder if it''s okay.');
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('a5e76559-5c06-4604-9949-75990d8a8a89', '行[い]こうかな。', '갈까.', 'Maybe I''ll go.');
INSERT INTO grammar (id, pattern, meaning, connection, jlpt_level, conversation_level, is_core) VALUES ('80787bf4-764c-443a-8f5b-ece9c4d4289c', '～かなと思[おも]って', '~일까 해서', '文[ぶん] + かなと思[おも]って', 4, 4, TRUE);
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('80787bf4-764c-443a-8f5b-ece9c4d4289c', '今日[きょう]はやめようかなと思[おも]って。', '오늘은 그만할까 해서.', 'I was thinking of stopping today.');
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('80787bf4-764c-443a-8f5b-ece9c4d4289c', '連絡[れんらく]しようかなと思[おも]って。', '연락할까 해서.', 'I was thinking of messaging.');
INSERT INTO grammar (id, pattern, meaning, connection, jlpt_level, conversation_level, is_core) VALUES ('2787be3b-dc22-4a7a-88a5-3dff5a9f268f', '～かも', '~일지도', '文[ぶん] + かも', 4, 5, TRUE);
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('2787be3b-dc22-4a7a-88a5-3dff5a9f268f', '雨[あめ]かも。', '비일지도.', 'It might rain.');
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('2787be3b-dc22-4a7a-88a5-3dff5a9f268f', '遅[おく]れるかも。', '늦을지도 몰라.', 'I might be late.');
INSERT INTO grammar (id, pattern, meaning, connection, jlpt_level, conversation_level, is_core) VALUES ('8e210034-784c-468c-bd72-131382ff211d', '～から', '~이기 때문에', '문장 + から', 5, 5, TRUE);
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('8e210034-784c-468c-bd72-131382ff211d', '雨[あめ]ですから、行[い]きません。', '비가 와서 안 가요.', 'I''m not going because it''s raining.');
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('8e210034-784c-468c-bd72-131382ff211d', '忙[いそが]しいから、後[あと]で。', '바빠서 나중에.', 'Because I''m busy, later.');
INSERT INTO grammar (id, pattern, meaning, connection, jlpt_level, conversation_level, is_core) VALUES ('0817e15e-8516-48ba-8ec3-958fef6ffb72', '～からさ', '~라서 말인데 (구어 이유)', '文[ぶん] + からさ', 4, 4, FALSE);
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('0817e15e-8516-48ba-8ec3-958fef6ffb72', '忙[いそが]しいからさ、今日は無理[むり]。', '바쁘니까, 오늘은 무리야.', 'I''m busy, so today won''t work.');
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('0817e15e-8516-48ba-8ec3-958fef6ffb72', '遠[とお]いからさ、また今度[こんど]ね。', '멀어서, 다음에 하자.', 'It''s far, so maybe next time.');
INSERT INTO grammar (id, pattern, meaning, connection, jlpt_level, conversation_level, is_core) VALUES ('c368e0ee-8e79-4ec9-8e62-182cc5f54fe7', '～からなんだけど', '~라서 말인데', '文[ぶん] + からなんだけど', 4, 4, FALSE);
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('c368e0ee-8e79-4ec9-8e62-182cc5f54fe7', '急[いそ]いでるからなんだけど、先[さき]に行[い]くね。', '급해서 먼저 갈게.', 'I''m in a hurry, so I''ll go ahead.');
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('c368e0ee-8e79-4ec9-8e62-182cc5f54fe7', 'ちょっと聞[き]きたいからなんだけど。', '좀 물어보고 싶은데.', 'I wanted to ask something.');
INSERT INTO grammar (id, pattern, meaning, connection, jlpt_level, conversation_level, is_core) VALUES ('0132184d-cd32-4128-aa11-82d709229a36', '～が', '하지만 / 그리고', '문장 + が', 5, 5, FALSE);
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('0132184d-cd32-4128-aa11-82d709229a36', '行[い]きたいですが、時間[じかん]がないです。', '가고 싶지만 시간이 없어요.', 'I want to go, but I don''t have time.');
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('0132184d-cd32-4128-aa11-82d709229a36', '安[やす]いですが、おいしいです。', '싸지만 맛있어요.', 'It''s cheap, but tasty.');
INSERT INTO grammar (id, pattern, meaning, connection, jlpt_level, conversation_level, is_core) VALUES ('9ae4ad33-bacb-4b29-b593-df75906f3f4d', '～ことにする', '~하기로 하다 (결정)', '文[ぶん] + ことにする', 4, 5, FALSE);
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('9ae4ad33-bacb-4b29-b593-df75906f3f4d', '今日[きょう]は早[はや]く帰[かえ]ることにする。', '오늘은 일찍 가기로 했어.', 'I''ve decided to go home early.');
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('9ae4ad33-bacb-4b29-b593-df75906f3f4d', '旅行[りょこう]は来月[らいげつ]にすることにした。', '여행은 다음 달로 하기로 했어.', 'I decided to do the trip next month.');
INSERT INTO grammar (id, pattern, meaning, connection, jlpt_level, conversation_level, is_core) VALUES ('4921fae4-66d5-49b0-a962-35a2c4fb156b', '～じゃん', '~잖아 (강조/확인)', '문장 + じゃん', 5, 5, FALSE);
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('4921fae4-66d5-49b0-a962-35a2c4fb156b', 'それ、いいじゃん。', '그거 좋잖아.', 'That''s good, right?');
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('4921fae4-66d5-49b0-a962-35a2c4fb156b', 'もう終[お]わったじゃん。', '이미 끝났잖아.', 'It''s already done.');
INSERT INTO grammar (id, pattern, meaning, connection, jlpt_level, conversation_level, is_core) VALUES ('1d56236c-eaaa-49ec-965d-16bb00825fad', '～せいで', '~때문에 (부정)', '名詞[めいし]/文[ぶん] + せいで', 4, 4, FALSE);
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('1d56236c-eaaa-49ec-965d-16bb00825fad', '雨[あめ]のせいで遅[おく]れた。', '비 때문에 늦었어.', 'I was late because of the rain.');
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('1d56236c-eaaa-49ec-965d-16bb00825fad', '彼[かれ]のせいで失敗[しっぱい]した。', '그 사람 때문에 실패했어.', 'I failed because of him.');
INSERT INTO grammar (id, pattern, meaning, connection, jlpt_level, conversation_level, is_core) VALUES ('315f4ef1-7fb4-49df-a679-58443f246e7f', '～そうです', '~인 것 같다 (보이는 상태)', '형용사/동사 ます형 어간 + そうです', 5, 5, FALSE);
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('315f4ef1-7fb4-49df-a679-58443f246e7f', 'おいしそうですね。', '맛있어 보이네요.', 'It looks tasty.');
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('315f4ef1-7fb4-49df-a679-58443f246e7f', '雨[あめ]が降[ふ]りそうです。', '비 올 것 같아요.', 'It looks like it will rain.');
INSERT INTO grammar (id, pattern, meaning, connection, jlpt_level, conversation_level, is_core) VALUES ('c04f15f1-233e-499a-a75f-63c5dbcf3dfd', '～たいです', '~하고 싶다', '동사 ます형 + たいです', 5, 5, TRUE);
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('c04f15f1-233e-499a-a75f-63c5dbcf3dfd', '日本語[にほんご]を話[はな]したいです。', '일본어를 말하고 싶어요.', 'I want to speak Japanese.');
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('c04f15f1-233e-499a-a75f-63c5dbcf3dfd', '今日[きょう]は早[はや]く帰[かえ]りたいです。', '오늘은 빨리 가고 싶어요.', 'I want to go home early.');
INSERT INTO grammar (id, pattern, meaning, connection, jlpt_level, conversation_level, is_core) VALUES ('579348de-3906-4d26-b33e-58f455869aa2', '～ため', '~때문에 (짧게)', '名詞[めいし]/動詞[どうし]辞書形[じしょけい] + ため', 4, 4, FALSE);
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('579348de-3906-4d26-b33e-58f455869aa2', '雨[あめ]のため中止[ちゅうし]。', '비로 인해 취소.', 'Canceled due to rain.');
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('579348de-3906-4d26-b33e-58f455869aa2', '事故[じこ]のため遅[おく]れます。', '사고로 늦습니다.', 'I''ll be late due to an accident.');
INSERT INTO grammar (id, pattern, meaning, connection, jlpt_level, conversation_level, is_core) VALUES ('f2c32f07-7b23-4b47-a276-bdad789c11b3', '～ために', '~하기 위해', '動詞[どうし]辞書形[じしょけい] + ために', 4, 5, FALSE);
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('f2c32f07-7b23-4b47-a276-bdad789c11b3', '日本語[にほんご]を勉強[べんきょう]するために来[き]た。', '일본어 공부하려고 왔어.', 'I came to study Japanese.');
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('f2c32f07-7b23-4b47-a276-bdad789c11b3', '健康[けんこう]のために運動[うんどう]する。', '건강을 위해 운동해.', 'I exercise for my health.');
INSERT INTO grammar (id, pattern, meaning, connection, jlpt_level, conversation_level, is_core) VALUES ('165b4091-acc2-48dd-9c01-c6b743a97895', '～たら', '~하면 / ~했을 때', '動詞[どうし]た形[けい] + ら', 4, 5, TRUE);
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('165b4091-acc2-48dd-9c01-c6b743a97895', '終[お]わったら連絡[れんらく]して。', '끝나면 연락해.', 'Contact me when you''re done.');
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('165b4091-acc2-48dd-9c01-c6b743a97895', '着[つ]いたら教[おし]えて。', '도착하면 알려줘.', 'Let me know when you arrive.');
INSERT INTO grammar (id, pattern, meaning, connection, jlpt_level, conversation_level, is_core) VALUES ('1f69171f-5732-416d-8c0d-5cea0c0b76b7', '～だから', '~니까', '文[ぶん] + だから', 4, 5, TRUE);
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('1f69171f-5732-416d-8c0d-5cea0c0b76b7', '忙[いそが]しいだから無理[むり]。', '바쁘니까 무리야.', 'I''m busy, so I can''t.');
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('1f69171f-5732-416d-8c0d-5cea0c0b76b7', '今日[きょう]は休[やす]みだから。', '오늘은 쉬는 날이니까.', 'Because today is a day off.');
INSERT INTO grammar (id, pattern, meaning, connection, jlpt_level, conversation_level, is_core) VALUES ('e87987fb-f0eb-4af5-8dce-b6d28b976ee8', '～だったら', '~라면 (회화형 조건)', '文[ぶん] + だったら', 4, 5, TRUE);
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('e87987fb-f0eb-4af5-8dce-b6d28b976ee8', '雨[あめ]だったら家[いえ]にいよう。', '비면 집에 있자.', 'If it rains, let''s stay home.');
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('e87987fb-f0eb-4af5-8dce-b6d28b976ee8', '無理[むり]だったら言[い]って。', '무리면 말해줘.', 'If it''s impossible, tell me.');
INSERT INTO grammar (id, pattern, meaning, connection, jlpt_level, conversation_level, is_core) VALUES ('78b6cfd4-b1c0-429f-9a4c-99f923f5c287', '～ちょっと', '조금 / 좀…', '부사', 5, 5, FALSE);
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('78b6cfd4-b1c0-429f-9a4c-99f923f5c287', 'ちょっと高[たか]いです。', '좀 비싸요.', 'It''s a bit expensive.');
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('78b6cfd4-b1c0-429f-9a4c-99f923f5c287', '今日[きょう]はちょっと忙[いそが]しいです。', '오늘은 좀 바빠요.', 'I''m a bit busy today.');
INSERT INTO grammar (id, pattern, meaning, connection, jlpt_level, conversation_level, is_core) VALUES ('ebd64504-051a-40bc-ace3-419c32ab4344', '～って', '~라고 (인용/주제)', '문장 + って', 5, 5, FALSE);
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('ebd64504-051a-40bc-ace3-419c32ab4344', '明日[あした]休[やす]みだって。', '내일 쉰대.', 'They said tomorrow is off.');
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('ebd64504-051a-40bc-ace3-419c32ab4344', 'それって本当[ほんとう]？', '그게 진짜야?', 'Is that true?');
INSERT INTO grammar (id, pattern, meaning, connection, jlpt_level, conversation_level, is_core) VALUES ('532ec182-44aa-4041-a012-714990964c10', '～っていう理由[りゆう]で', '~라는 이유로', '文[ぶん] + っていう理由[りゆう]で', 4, 4, FALSE);
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('532ec182-44aa-4041-a012-714990964c10', '時間[じかん]がないっていう理由[りゆう]で断[ことわ]った。', '시간 없다는 이유로 거절했어.', 'I declined saying I had no time.');
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('532ec182-44aa-4041-a012-714990964c10', '体調[たいちょう]が悪[わる]いっていう理由[りゆう]で休[やす]んだ。', '컨디션 안 좋다는 이유로 쉬었어.', 'I took a day off saying I felt unwell.');
INSERT INTO grammar (id, pattern, meaning, connection, jlpt_level, conversation_level, is_core) VALUES ('0a4809f7-8c15-4bf8-853e-1a41d1b1c4db', '～ってことで', '~라는 이유로 / 그래서', '文[ぶん] + ってことで', 4, 5, FALSE);
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('0a4809f7-8c15-4bf8-853e-1a41d1b1c4db', '忙[いそが]しいってことで欠席[けっせき]します。', '바쁘다는 이유로 결석할게.', 'I''ll be absent due to being busy.');
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('0a4809f7-8c15-4bf8-853e-1a41d1b1c4db', 'じゃあ、また今度[こんど]ってことで。', '그럼 다음에 하는 걸로.', 'Let''s do it next time.');
INSERT INTO grammar (id, pattern, meaning, connection, jlpt_level, conversation_level, is_core) VALUES ('d593b709-ba74-4496-909e-c5f12f1c8ffb', '～ってことは', '~라는 건… (추론/정리)', '文[ぶん] + ってことは', 4, 5, TRUE);
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('d593b709-ba74-4496-909e-c5f12f1c8ffb', '今[いま]の話[はなし]ってことは、来週[らいしゅう]は無理[むり]？', '지금 말로는 다음 주는 무리야?', 'So, that means next week won''t work?');
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('d593b709-ba74-4496-909e-c5f12f1c8ffb', '終[お]わったってことは、もう帰[かえ]った？', '끝났다는 건, 벌써 갔어?', 'So that means they''re already gone?');
INSERT INTO grammar (id, pattern, meaning, connection, jlpt_level, conversation_level, is_core) VALUES ('029d4243-8787-4ae7-a9ce-03e6df125a19', '～って感[かん]じ', '~라는 느낌', '文[ぶん] + って感[かん]じ', 4, 5, TRUE);
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('029d4243-8787-4ae7-a9ce-03e6df125a19', 'まあ、そんな感[かん]じ。', '뭐 그런 느낌이야.', 'Yeah, something like that.');
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('029d4243-8787-4ae7-a9ce-03e6df125a19', 'とりあえず行[い]くって感[かん]じ。', '일단 가는 느낌.', 'For now, let''s go.');
INSERT INTO grammar (id, pattern, meaning, connection, jlpt_level, conversation_level, is_core) VALUES ('afcd6f8e-abb7-4590-8e19-da2b120b19e5', '～って感[かん]じで', '~라는 느낌으로', '文[ぶん] + って感[かん]じで', 4, 5, FALSE);
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('afcd6f8e-abb7-4590-8e19-da2b120b19e5', 'とりあえず行[い]くって感[かん]じで。', '일단 가는 느낌으로.', 'For now, let''s just go—something like that.');
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('afcd6f8e-abb7-4590-8e19-da2b120b19e5', 'まあ、そんな感[かん]じで大丈夫[だいじょうぶ]。', '뭐, 그런 느낌이면 괜찮아.', 'Yeah, that kind of vibe is fine.');
INSERT INTO grammar (id, pattern, meaning, connection, jlpt_level, conversation_level, is_core) VALUES ('20ae71bc-5614-4599-be17-ef8eff2707b8', '～って感じ', '~같은 느낌', '문장 + って感じ', 5, 5, FALSE);
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('20ae71bc-5614-4599-be17-ef8eff2707b8', 'まあ、そんな感じ。', '뭐 그런 느낌.', 'Yeah, something like that.');
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('20ae71bc-5614-4599-be17-ef8eff2707b8', '初心者[しょしんしゃ]って感じ。', '초보 같은 느낌.', 'Feels like a beginner.');
INSERT INTO grammar (id, pattern, meaning, connection, jlpt_level, conversation_level, is_core) VALUES ('598c2583-83a5-4fb5-ad9d-2e38dc45b8f1', '～って理由[りゆう]で', '~라는 이유로', '文[ぶん] + って理由[りゆう]で', 4, 4, FALSE);
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('598c2583-83a5-4fb5-ad9d-2e38dc45b8f1', '時間[じかん]がないって理由[りゆう]で断[ことわ]った。', '시간 없다는 이유로 거절했어.', 'I declined saying I had no time.');
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('598c2583-83a5-4fb5-ad9d-2e38dc45b8f1', '体調[たいちょう]が悪[わる]いって理由[りゆう]で休[やす]んだ。', '컨디션 안 좋다는 이유로 쉬었어.', 'I took a day off for health reasons.');
INSERT INTO grammar (id, pattern, meaning, connection, jlpt_level, conversation_level, is_core) VALUES ('a37d5ad1-5083-4eb1-a09f-9fb699ac1843', '～っぽい', '~같아 보이다', '名詞[めいし]/形容詞[けいようし] + っぽい', 4, 4, TRUE);
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('a37d5ad1-5083-4eb1-a09f-9fb699ac1843', '今日[きょう]は風邪[かぜ]っぽい。', '오늘 감기 기운이 있어.', 'I feel like I''m catching a cold.');
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('a37d5ad1-5083-4eb1-a09f-9fb699ac1843', '子[こ]どもっぽいね。', '애같네.', 'Kind of childish.');
INSERT INTO grammar (id, pattern, meaning, connection, jlpt_level, conversation_level, is_core) VALUES ('258c5221-54fb-484f-b25d-76d85c71366c', '～つい', '무심코 / 나도 모르게', '副詞[ふくし]', 4, 5, FALSE);
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('258c5221-54fb-484f-b25d-76d85c71366c', 'つい食[た]べすぎた。', '나도 모르게 너무 먹었어.', 'I ate too much without thinking.');
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('258c5221-54fb-484f-b25d-76d85c71366c', 'つい言[い]ってしまった。', '무심코 말해버렸어.', 'I said it without meaning to.');
INSERT INTO grammar (id, pattern, meaning, connection, jlpt_level, conversation_level, is_core) VALUES ('c8d67163-9263-4ec2-975b-6fcb00744daa', '～つもりだ', '~할 생각이다', '動詞[どうし]辞書形[じしょけい] + つもりだ', 4, 5, FALSE);
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('c8d67163-9263-4ec2-975b-6fcb00744daa', '来週[らいしゅう]行[い]くつもりだ。', '다음 주에 갈 생각이야.', 'I plan to go next week.');
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('c8d67163-9263-4ec2-975b-6fcb00744daa', '今日[きょう]は早[はや]く帰[かえ]るつもり。', '오늘은 일찍 갈 생각이야.', 'I plan to go home early today.');
INSERT INTO grammar (id, pattern, meaning, connection, jlpt_level, conversation_level, is_core) VALUES ('7bf4aa99-67d0-4bd5-8597-bf44e36e39b2', '～てあげる', '~해 주다 (내가 → 상대)', '動詞[どうし]て形[けい] + あげる', 4, 5, FALSE);
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('7bf4aa99-67d0-4bd5-8597-bf44e36e39b2', '私[わたし]が手伝[てつだ]ってあげる。', '내가 도와줄게.', 'I''ll help you.');
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('7bf4aa99-67d0-4bd5-8597-bf44e36e39b2', '説明[せつめい]してあげる。', '설명해 줄게.', 'I''ll explain it to you.');
INSERT INTO grammar (id, pattern, meaning, connection, jlpt_level, conversation_level, is_core) VALUES ('dc1f4f4f-24ff-495a-801a-cf01d7f490ab', '～ている', '~하고 있다', '동사 て형 + いる', 5, 5, TRUE);
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('dc1f4f4f-24ff-495a-801a-cf01d7f490ab', '今[いま]、勉強[べんきょう]しています。', '지금 공부하고 있어요.', 'I''m studying now.');
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('dc1f4f4f-24ff-495a-801a-cf01d7f490ab', '何[なに]をしていますか。', '뭐 하고 있어요?', 'What are you doing?');
INSERT INTO grammar (id, pattern, meaning, connection, jlpt_level, conversation_level, is_core) VALUES ('bde4118d-7b22-4bbb-8f6f-434a9f712a4c', '～ておく', '~미리 ~하다', '動詞[どうし]て形[けい] + おく', 4, 5, FALSE);
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('bde4118d-7b22-4bbb-8f6f-434a9f712a4c', '先[さき]に予約[よやく]しておく。', '미리 예약해 둘게.', 'I''ll make a reservation in advance.');
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('bde4118d-7b22-4bbb-8f6f-434a9f712a4c', '飲[の]み物[もの]を買[か]っておいた。', '마실 걸 미리 사뒀어.', 'I bought drinks in advance.');
INSERT INTO grammar (id, pattern, meaning, connection, jlpt_level, conversation_level, is_core) VALUES ('5ea150be-32b2-435c-b72e-071a7744c2d3', '～てください', '~해주세요', '동사 て형 + ください', 5, 5, TRUE);
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('5ea150be-32b2-435c-b72e-071a7744c2d3', 'ちょっと待[ま]ってください。', '잠깐만 기다려 주세요.', 'Please wait a moment.');
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('5ea150be-32b2-435c-b72e-071a7744c2d3', 'ゆっくり話[はな]してください。', '천천히 말해 주세요.', 'Please speak slowly.');
INSERT INTO grammar (id, pattern, meaning, connection, jlpt_level, conversation_level, is_core) VALUES ('36e875d6-fe09-42ce-9852-6a327de84304', '～てくる', '~하고 오다 / 변화', '動詞[どうし]て形[けい] + くる', 4, 5, FALSE);
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('36e875d6-fe09-42ce-9852-6a327de84304', 'ちょっと見[み]てくる。', '잠깐 보고 올게.', 'I''ll go take a look.');
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('36e875d6-fe09-42ce-9852-6a327de84304', '雨[あめ]が降[ふ]ってきた。', '비가 오기 시작했어.', 'It started raining.');
INSERT INTO grammar (id, pattern, meaning, connection, jlpt_level, conversation_level, is_core) VALUES ('84e0d385-f9b3-4da6-b163-347206226da1', '～てくれる？', '~해줄래?', '동사 て형 + くれる？', 5, 5, FALSE);
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('84e0d385-f9b3-4da6-b163-347206226da1', 'ちょっと待[ま]ってくれる？', '잠깐 기다려줄래?', 'Can you wait a moment?');
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('84e0d385-f9b3-4da6-b163-347206226da1', '教[おし]えてくれる？', '가르쳐줄래?', 'Can you tell me?');
INSERT INTO grammar (id, pattern, meaning, connection, jlpt_level, conversation_level, is_core) VALUES ('b2923995-881a-4c67-8400-5e47dcf53ee8', '～てしまう', '~해버리다 / 완료', '動詞[どうし]て形[けい] + しまう', 4, 5, FALSE);
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('b2923995-881a-4c67-8400-5e47dcf53ee8', '忘[わす]れてしまった。', '깜빡 잊어버렸어.', 'I completely forgot.');
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('b2923995-881a-4c67-8400-5e47dcf53ee8', '全部[ぜんぶ]食[た]べてしまった。', '전부 먹어버렸어.', 'I ate it all.');
INSERT INTO grammar (id, pattern, meaning, connection, jlpt_level, conversation_level, is_core) VALUES ('89a013e0-6b18-4a0e-9581-2af69123b2f2', '～てほしい', '~해줬으면 하다', '動詞[どうし]て形[けい] + ほしい', 4, 5, FALSE);
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('89a013e0-6b18-4a0e-9581-2af69123b2f2', '早[はや]く返事[へんじ]してほしい。', '빨리 답장해줬으면 해.', 'I want you to reply quickly.');
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('89a013e0-6b18-4a0e-9581-2af69123b2f2', '静[しず]かにしてほしい。', '조용히 해줬으면 해.', 'I want you to be quiet.');
INSERT INTO grammar (id, pattern, meaning, connection, jlpt_level, conversation_level, is_core) VALUES ('28a0215d-cec6-42f2-bce7-344d0ccbefc5', '～てみる', '~시험 삼아 ~하다', '動詞[どうし]て形[けい] + みる', 4, 5, FALSE);
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('28a0215d-cec6-42f2-bce7-344d0ccbefc5', '一度[いちど]食[た]べてみる。', '한 번 먹어볼게.', 'I''ll try eating it.');
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('28a0215d-cec6-42f2-bce7-344d0ccbefc5', '日本語[にほんご]で話[はな]してみて。', '일본어로 말해봐.', 'Try speaking in Japanese.');
INSERT INTO grammar (id, pattern, meaning, connection, jlpt_level, conversation_level, is_core) VALUES ('ae0a00fb-a060-429f-8d04-e9b6df5d632c', '～てもいいですか', '~해도 돼요?', '동사 て형 + もいいですか', 5, 5, FALSE);
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('ae0a00fb-a060-429f-8d04-e9b6df5d632c', 'ここに座[すわ]ってもいいですか。', '여기 앉아도 될까요?', 'May I sit here?');
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('ae0a00fb-a060-429f-8d04-e9b6df5d632c', '写真[しゃしん]を撮[と]ってもいいですか。', '사진 찍어도 돼요?', 'Can I take a photo?');
INSERT INTO grammar (id, pattern, meaning, connection, jlpt_level, conversation_level, is_core) VALUES ('54b4048f-a687-4991-9528-06da8c65e8f2', '～てもらう', '~해 달라고 하다', '動詞[どうし]て形[けい] + もらう', 4, 5, FALSE);
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('54b4048f-a687-4991-9528-06da8c65e8f2', '友[とも]だちに見[み]てもらった。', '친구에게 봐 달라고 했어.', 'I had my friend check it.');
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('54b4048f-a687-4991-9528-06da8c65e8f2', '先生[せんせい]に教[おし]えてもらう。', '선생님께 가르쳐 달라고 할게.', 'I''ll ask the teacher to teach me.');
INSERT INTO grammar (id, pattern, meaning, connection, jlpt_level, conversation_level, is_core) VALUES ('41f8b958-36a2-4a2f-81ac-be012c190ef0', '～てもらえる？', '~해줄 수 있어?', '동사 て형 + もらえる？', 5, 5, FALSE);
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('41f8b958-36a2-4a2f-81ac-be012c190ef0', '手伝[てつだ]ってもらえる？', '도와줄 수 있어?', 'Can you help me?');
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('41f8b958-36a2-4a2f-81ac-be012c190ef0', '見[み]てもらえる？', '봐줄 수 있어?', 'Can you check it?');
INSERT INTO grammar (id, pattern, meaning, connection, jlpt_level, conversation_level, is_core) VALUES ('ea915ae0-57fa-48d2-ae37-3358288c0333', '～てる', '~하고 있어 (구어)', '～ている → ～てる', 5, 5, TRUE);
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('ea915ae0-57fa-48d2-ae37-3358288c0333', '今[いま]、何[なに]してる？', '지금 뭐 하고 있어?', 'What are you doing now?');
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('ea915ae0-57fa-48d2-ae37-3358288c0333', 'テレビ見[み]てる。', 'TV 보고 있어.', 'I''m watching TV.');
INSERT INTO grammar (id, pattern, meaning, connection, jlpt_level, conversation_level, is_core) VALUES ('5cc80363-7dd9-41d9-b1df-c225b2c1c5eb', '～でいい', '~로 하면 돼', '명사 + でいい', 5, 5, FALSE);
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('5cc80363-7dd9-41d9-b1df-c225b2c1c5eb', 'これでいい？', '이걸로 돼?', 'Is this okay?');
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('5cc80363-7dd9-41d9-b1df-c225b2c1c5eb', 'コーヒーでいいです。', '커피로 할게요.', 'Coffee is fine.');
INSERT INTO grammar (id, pattern, meaning, connection, jlpt_level, conversation_level, is_core) VALUES ('1daab92c-dd98-47fe-a1e5-b484fddbd76e', '～ですか', '~입니까? (의문)', '문장 + ですか', 5, 5, TRUE);
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('1daab92c-dd98-47fe-a1e5-b484fddbd76e', 'それは本当[ほんとう]ですか？', '그거 진짜예요?', 'Is that true?');
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('1daab92c-dd98-47fe-a1e5-b484fddbd76e', '今[いま]、大丈夫[だいじょうぶ]ですか？', '지금 괜찮아요?', 'Are you okay now?');
INSERT INTO grammar (id, pattern, meaning, connection, jlpt_level, conversation_level, is_core) VALUES ('0c249070-aa89-4498-a3ec-f68e749d93c9', '～でもいい？', '~라도 괜찮아?', '명사 + でもいい？', 5, 5, FALSE);
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('0c249070-aa89-4498-a3ec-f68e749d93c9', '今[いま]でもいい？', '지금이라도 괜찮아?', 'Is now okay?');
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('0c249070-aa89-4498-a3ec-f68e749d93c9', 'これでもいい？', '이거라도 괜찮아?', 'Is this okay too?');
INSERT INTO grammar (id, pattern, meaning, connection, jlpt_level, conversation_level, is_core) VALUES ('2207e478-1680-46e5-8a28-9a25fb8b07c6', '～と', '~하면 (자연 결과)', '動詞[どうし]辞書形[じしょけい] + と', 4, 4, FALSE);
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('2207e478-1680-46e5-8a28-9a25fb8b07c6', '押[お]すと動[うご]く。', '누르면 움직여.', 'If you push it, it moves.');
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('2207e478-1680-46e5-8a28-9a25fb8b07c6', '春[はる]になると暖[あたた]かい。', '봄이 되면 따뜻해.', 'When spring comes, it''s warm.');
INSERT INTO grammar (id, pattern, meaning, connection, jlpt_level, conversation_level, is_core) VALUES ('fd285f43-663f-464f-b288-b4e01175996a', '～とかどう？', '~같은 건 어때?', '명사 + とかどう？', 5, 5, FALSE);
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('fd285f43-663f-464f-b288-b4e01175996a', '映画[えいが]とかどう？', '영화 같은 건 어때?', 'How about a movie?');
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('fd285f43-663f-464f-b288-b4e01175996a', '土曜[どよう]とかどうですか？', '토요일 같은 건 어때요?', 'How about Saturday?');
INSERT INTO grammar (id, pattern, meaning, connection, jlpt_level, conversation_level, is_core) VALUES ('7ff13c53-cc45-45ad-8339-bac64720de51', '～としたら', '~라고 가정하면', '文[ぶん] + としたら', 4, 4, TRUE);
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('7ff13c53-cc45-45ad-8339-bac64720de51', '今[いま]行[い]くとしたら何時[なんじ]？', '지금 가면 몇 시야?', 'If we go now, what time?');
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('7ff13c53-cc45-45ad-8339-bac64720de51', 'それが本当[ほんとう]だとしたら大変[たいへん]。', '그게 진짜라면 큰일이야.', 'If that''s true, it''s serious.');
INSERT INTO grammar (id, pattern, meaning, connection, jlpt_level, conversation_level, is_core) VALUES ('797dac3b-3c20-4e98-bb57-48b89aa450f7', '～と思[おも]う', '~라고 생각하다', '文[ぶん] + と思[おも]う', 4, 5, TRUE);
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('797dac3b-3c20-4e98-bb57-48b89aa450f7', 'それはいいと思[おも]う。', '그건 좋다고 생각해.', 'I think that''s good.');
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('797dac3b-3c20-4e98-bb57-48b89aa450f7', '彼[かれ]も来[く]ると思[おも]う。', '그도 올 거라고 생각해.', 'I think he''ll come.');
INSERT INTO grammar (id, pattern, meaning, connection, jlpt_level, conversation_level, is_core) VALUES ('fb21d65b-14a7-42e8-90b6-7da72fdda8fb', '～どうですか', '어때요?', 'どうですか', 5, 5, FALSE);
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('fb21d65b-14a7-42e8-90b6-7da72fdda8fb', 'この映画[えいが]はどうですか？', '이 영화 어때요?', 'How is this movie?');
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('fb21d65b-14a7-42e8-90b6-7da72fdda8fb', '今日[きょう]はどうですか？', '오늘 어때요?', 'How is today?');
INSERT INTO grammar (id, pattern, meaning, connection, jlpt_level, conversation_level, is_core) VALUES ('0a3f01a5-9f83-47c2-a911-3c1a38b67346', '～どれ', '어느 것', 'どれ', 5, 5, FALSE);
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('0a3f01a5-9f83-47c2-a911-3c1a38b67346', 'どれが好[す]きですか？', '어느 게 좋아요?', 'Which one do you like?');
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('0a3f01a5-9f83-47c2-a911-3c1a38b67346', 'どれにしますか？', '어느 걸로 할래요?', 'Which will you choose?');
INSERT INTO grammar (id, pattern, meaning, connection, jlpt_level, conversation_level, is_core) VALUES ('4ea26e95-86ae-4dd8-b19a-0381b1f2aa10', '～ないなら', '~안 하면', '動詞[どうし]ない形[けい] + なら', 4, 4, TRUE);
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('4ea26e95-86ae-4dd8-b19a-0381b1f2aa10', '行[い]かないなら先[さき]に帰[かえ]る。', '안 갈 거면 먼저 갈게.', 'If you''re not going, I''ll go first.');
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('4ea26e95-86ae-4dd8-b19a-0381b1f2aa10', '無理[むり]しないなら大丈夫[だいじょうぶ]。', '무리 안 하면 괜찮아.', 'If you don''t push yourself, it''s fine.');
INSERT INTO grammar (id, pattern, meaning, connection, jlpt_level, conversation_level, is_core) VALUES ('35c36230-1a67-4591-952d-5f4074813ae0', '～なら', '~라면 (상대 말 받아 조건)', '文[ぶん]/名詞[めいし] + なら', 4, 5, TRUE);
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('35c36230-1a67-4591-952d-5f4074813ae0', '土曜[どよう]なら行[い]けるよ。', '토요일이면 갈 수 있어.', 'If it''s Saturday, I can go.');
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('35c36230-1a67-4591-952d-5f4074813ae0', 'それなら大丈夫[だいじょうぶ]。', '그렇다면 괜찮아.', 'In that case, it''s fine.');
INSERT INTO grammar (id, pattern, meaning, connection, jlpt_level, conversation_level, is_core) VALUES ('78997eb5-5dc3-4223-ab87-bfebdc03ab78', '～ならどうする？', '~라면 어떻게 할래?', '文[ぶん] + ならどうする', 4, 5, TRUE);
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('78997eb5-5dc3-4223-ab87-bfebdc03ab78', '君[きみ]だったらどうする？', '너라면 어떻게 할래?', 'What would you do?');
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('78997eb5-5dc3-4223-ab87-bfebdc03ab78', '雨[あめ]ならどうする？', '비면 어떻게 할 거야?', 'What if it rains?');
INSERT INTO grammar (id, pattern, meaning, connection, jlpt_level, conversation_level, is_core) VALUES ('23d07e8c-b947-47ee-80ba-c2be06bb2ef8', '～ね', '~죠 / 그렇죠?', '문장 + ね', 5, 5, TRUE);
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('23d07e8c-b947-47ee-80ba-c2be06bb2ef8', '今日[きょう]は暑[あつ]いですね。', '오늘 덥네요.', 'It''s hot today, right?');
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('23d07e8c-b947-47ee-80ba-c2be06bb2ef8', 'この店[みせ]、いいですね。', '이 가게 좋네요.', 'This place is nice, right?');
INSERT INTO grammar (id, pattern, meaning, connection, jlpt_level, conversation_level, is_core) VALUES ('aa49b0c9-7959-4a85-a4f7-6927a2702752', '～ので', '~해서/때문에 (부드러운 이유)', '文[ぶん] + ので', 4, 5, TRUE);
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('aa49b0c9-7959-4a85-a4f7-6927a2702752', '今日[きょう]は忙[いそが]しいので、また後[あと]で。', '오늘 바빠서, 나중에.', 'I''m busy today, so later.');
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('aa49b0c9-7959-4a85-a4f7-6927a2702752', '雨[あめ]なので、家[いえ]にいます。', '비라서 집에 있어.', 'It''s raining, so I''m staying home.');
INSERT INTO grammar (id, pattern, meaning, connection, jlpt_level, conversation_level, is_core) VALUES ('ece26c7b-c51d-40cd-8e14-98c46deba5b5', '～のでしょうか', '~인 걸까요? (완곡 질문)', '文[ぶん] + のでしょうか', 4, 4, FALSE);
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('ece26c7b-c51d-40cd-8e14-98c46deba5b5', 'これで大丈夫[だいじょうぶ]なのでしょうか。', '이거 괜찮을까요?', 'I wonder if this is okay.');
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('ece26c7b-c51d-40cd-8e14-98c46deba5b5', '今[いま]行[い]ってもいいのでしょうか。', '지금 가도 될까요?', 'Would it be okay to go now?');
INSERT INTO grammar (id, pattern, meaning, connection, jlpt_level, conversation_level, is_core) VALUES ('fd92ed99-fc22-4ddc-9fd7-4faf4beef239', '～のは', '~한 건', '文[ぶん] + のは', 4, 4, FALSE);
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('fd92ed99-fc22-4ddc-9fd7-4faf4beef239', '来[こ]なかったのは雨[あめ]だから。', '안 온 건 비 때문이야.', 'The reason I didn''t come is because it rained.');
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('fd92ed99-fc22-4ddc-9fd7-4faf4beef239', '遅[おく]れたのは事故[じこ]だ。', '늦은 건 사고 때문이야.', 'The reason I was late was an accident.');
INSERT INTO grammar (id, pattern, meaning, connection, jlpt_level, conversation_level, is_core) VALUES ('4cdd426a-b64a-4f80-866c-8d2f9792c29a', '～ば', '~하면 (조건)', '動詞[どうし]ば形[けい]', 4, 4, FALSE);
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('4cdd426a-b64a-4f80-866c-8d2f9792c29a', '安[やす]ければ買[か]う。', '싸면 살게.', 'If it''s cheap, I''ll buy it.');
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('4cdd426a-b64a-4f80-866c-8d2f9792c29a', '時間[じかん]があれば行[い]く。', '시간 있으면 갈게.', 'If I have time, I''ll go.');
INSERT INTO grammar (id, pattern, meaning, connection, jlpt_level, conversation_level, is_core) VALUES ('27565279-790b-46dd-a75a-29f9422b2ce6', '～ました', '~했습니다 (과거)', '동사 ます형 + ました', 5, 5, TRUE);
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('27565279-790b-46dd-a75a-29f9422b2ce6', '昨日[きのう]映画[えいが]を見[み]ました。', '어제 영화를 봤어요.', 'I watched a movie yesterday.');
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('27565279-790b-46dd-a75a-29f9422b2ce6', 'さっき帰[かえ]りました。', '방금 돌아왔어요.', 'I just got back.');
INSERT INTO grammar (id, pattern, meaning, connection, jlpt_level, conversation_level, is_core) VALUES ('6fc18aac-421b-4954-936f-d25cec78103c', '～ます', '~합니다 (정중)', '동사 ます형', 5, 5, TRUE);
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('6fc18aac-421b-4954-936f-d25cec78103c', '毎日[まいにち]コーヒーを飲[の]みます。', '매일 커피를 마셔요.', 'I drink coffee every day.');
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('6fc18aac-421b-4954-936f-d25cec78103c', '後[あと]で連絡[れんらく]します。', '나중에 연락할게요.', 'I''ll contact you later.');
INSERT INTO grammar (id, pattern, meaning, connection, jlpt_level, conversation_level, is_core) VALUES ('e9d1e97f-3ce5-48a6-9dcd-51bc41c25af5', '～ません', '~하지 않습니다', '동사 ます형 + ません', 5, 5, TRUE);
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('e9d1e97f-3ce5-48a6-9dcd-51bc41c25af5', '今日[きょう]は行[い]きません。', '오늘은 안 가요.', 'I''m not going today.');
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('e9d1e97f-3ce5-48a6-9dcd-51bc41c25af5', '肉[にく]は食[た]べません。', '고기는 안 먹어요.', 'I don''t eat meat.');
INSERT INTO grammar (id, pattern, meaning, connection, jlpt_level, conversation_level, is_core) VALUES ('ab1b300c-e7d7-4691-958a-59ee56baff8f', '～まだ', '아직', '부사', 5, 5, TRUE);
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('ab1b300c-e7d7-4691-958a-59ee56baff8f', 'まだ来[き]ていません。', '아직 안 왔어요.', 'They haven’t come yet.');
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('ab1b300c-e7d7-4691-958a-59ee56baff8f', 'まだ大丈夫[だいじょうぶ]です。', '아직 괜찮아요.', 'It''s still okay.');
INSERT INTO grammar (id, pattern, meaning, connection, jlpt_level, conversation_level, is_core) VALUES ('e0740709-77aa-4b5a-bf92-c04efd645d0b', '～みたい', '~인 것 같다', '文[ぶん] + みたい', 4, 4, FALSE);
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('e0740709-77aa-4b5a-bf92-c04efd645d0b', '彼[かれ]は来[こ]ないみたい。', '그는 안 올 것 같아.', 'Seems like he won''t come.');
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('e0740709-77aa-4b5a-bf92-c04efd645d0b', '雨[あめ]みたい。', '비인 것 같아.', 'Looks like rain.');
INSERT INTO grammar (id, pattern, meaning, connection, jlpt_level, conversation_level, is_core) VALUES ('a120f024-966a-44ed-96e6-952ee0faed54', '～みたいです', '~인 것 같다 (추측)', '문장 + みたいです', 5, 5, FALSE);
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('a120f024-966a-44ed-96e6-952ee0faed54', '彼[かれ]は来[こ]ないみたいです。', '그는 안 올 것 같아요.', 'It seems he won''t come.');
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('a120f024-966a-44ed-96e6-952ee0faed54', '疲[つか]れたみたいです。', '피곤한 것 같아요.', 'They look tired.');
INSERT INTO grammar (id, pattern, meaning, connection, jlpt_level, conversation_level, is_core) VALUES ('96ee0ef8-1c4b-4844-8e5b-b2c209252493', '～みたいな感[かん]じ', '~같은 느낌', '文[ぶん] + みたいな感[かん]じ', 4, 4, FALSE);
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('96ee0ef8-1c4b-4844-8e5b-b2c209252493', '大丈夫[だいじょうぶ]みたいな感[かん]じ。', '괜찮은 느낌이야.', 'It feels like it''s okay.');
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('96ee0ef8-1c4b-4844-8e5b-b2c209252493', '終[お]わったみたいな感[かん]じだね。', '끝난 느낌이네.', 'It feels like it''s over.');
INSERT INTO grammar (id, pattern, meaning, connection, jlpt_level, conversation_level, is_core) VALUES ('e3915372-a697-42b0-9f4f-f3adba40b72d', '～もう', '이미 / 벌써', '부사', 5, 5, TRUE);
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('e3915372-a697-42b0-9f4f-f3adba40b72d', 'もう食[た]べました。', '이미 먹었어요.', 'I already ate.');
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('e3915372-a697-42b0-9f4f-f3adba40b72d', 'もう帰[かえ]ります。', '이제 갈게요.', 'I''m leaving now.');
INSERT INTO grammar (id, pattern, meaning, connection, jlpt_level, conversation_level, is_core) VALUES ('6a817b0e-2566-4d63-844c-92bebd860d3d', '～よ', '~야 / ~거든', '문장 + よ', 5, 5, TRUE);
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('6a817b0e-2566-4d63-844c-92bebd860d3d', 'これ、おいしいですよ。', '이거 맛있어요.', 'This is good.');
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('6a817b0e-2566-4d63-844c-92bebd860d3d', '明日[あした]は休[やす]みですよ。', '내일 쉬는 날이에요.', 'Tomorrow is a day off.');
INSERT INTO grammar (id, pattern, meaning, connection, jlpt_level, conversation_level, is_core) VALUES ('bec565d3-a066-446e-aabb-8ad3f95a5d1b', '～ようかな', '~할까 (부드러운 결정)', '동사 사전형 + ようかな', 5, 5, FALSE);
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('bec565d3-a066-446e-aabb-8ad3f95a5d1b', '帰[かえ]ろうかな。', '갈까.', 'Maybe I''ll go home.');
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('bec565d3-a066-446e-aabb-8ad3f95a5d1b', '聞[き]いてみようかな。', '물어볼까.', 'Maybe I''ll ask.');
INSERT INTO grammar (id, pattern, meaning, connection, jlpt_level, conversation_level, is_core) VALUES ('51cc1595-2214-4409-bd94-609240d86d1a', '～ようと思[おも]う', '~하려고 생각하다', '動詞[どうし]意向形[いこうけい] + と思[おも]う', 4, 5, FALSE);
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('51cc1595-2214-4409-bd94-609240d86d1a', '早[はや]く寝[ね]ようと思[おも]う。', '일찍 자려고 해.', 'I think I''ll sleep early.');
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('51cc1595-2214-4409-bd94-609240d86d1a', '明日[あした]行[い]こうと思[おも]う。', '내일 가려고 해.', 'I think I''ll go tomorrow.');
INSERT INTO grammar (id, pattern, meaning, connection, jlpt_level, conversation_level, is_core) VALUES ('4b76398e-372d-4f97-9dc7-4c60d006c0ca', '～ような感[かん]じ', '~같은 느낌', '文[ぶん] + ような感[かん]じ', 4, 4, TRUE);
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('4b76398e-372d-4f97-9dc7-4c60d006c0ca', '大丈夫[だいじょうぶ]な感[かん]じ。', '괜찮은 느낌이야.', 'Feels okay.');
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('4b76398e-372d-4f97-9dc7-4c60d006c0ca', '終[お]わったような感[かん]じ。', '끝난 느낌이야.', 'Feels finished.');
INSERT INTO grammar (id, pattern, meaning, connection, jlpt_level, conversation_level, is_core) VALUES ('5ddaf6c8-c397-45a5-92f6-9d39a347d259', '～ようにする', '~하려고 하다 / 습관으로 하다', '動詞[どうし]辞書形[じしょけい] + ようにする', 4, 5, FALSE);
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('5ddaf6c8-c397-45a5-92f6-9d39a347d259', '毎日[まいにち]運動[うんどう]するようにしている。', '매일 운동하려고 해.', 'I try to exercise every day.');
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('5ddaf6c8-c397-45a5-92f6-9d39a347d259', '早[はや]く寝[ね]るようにする。', '일찍 자려고 해.', 'I try to go to bed early.');
INSERT INTO grammar (id, pattern, meaning, connection, jlpt_level, conversation_level, is_core) VALUES ('866f4b5c-8c27-4b2b-a151-6e68e284e13d', '～ようになる', '~할 수 있게 되다', '動詞[どうし]辞書形[じしょけい] + ようになる', 4, 5, FALSE);
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('866f4b5c-8c27-4b2b-a151-6e68e284e13d', '日本語[にほんご]が分[わ]かるようになった。', '일본어를 알게 됐어.', 'I''ve come to understand Japanese.');
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('866f4b5c-8c27-4b2b-a151-6e68e284e13d', '早[はや]く起[お]きられるようになった。', '일찍 일어날 수 있게 됐어.', 'I can wake up early now.');
INSERT INTO grammar (id, pattern, meaning, connection, jlpt_level, conversation_level, is_core) VALUES ('8334e845-ceea-44ae-a0d9-cc7285202ec3', '～らしい', '~인 것 같다 (전언/추정)', '文[ぶん] + らしい', 4, 4, FALSE);
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('8334e845-ceea-44ae-a0d9-cc7285202ec3', '忙[いそが]しいらしい。', '바쁜 것 같아.', 'Seems busy.');
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('8334e845-ceea-44ae-a0d9-cc7285202ec3', '彼[かれ]は学生[がくせい]らしい。', '학생인 것 같아.', 'Seems like a student.');
INSERT INTO grammar (id, pattern, meaning, connection, jlpt_level, conversation_level, is_core) VALUES ('f44a2674-f9c2-4a44-88e1-6fbc92fa8885', '～わけだ', '~인 셈이다', '文[ぶん] + わけだ', 4, 5, FALSE);
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('f44a2674-f9c2-4a44-88e1-6fbc92fa8885', 'そういうわけだ。', '그래서 그런 거구나.', 'That explains it.');
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('f44a2674-f9c2-4a44-88e1-6fbc92fa8885', '忙[いそが]しいわけだ。', '바쁜 게 당연하네.', 'That makes sense.');
INSERT INTO grammar (id, pattern, meaning, connection, jlpt_level, conversation_level, is_core) VALUES ('d5dd8a59-fbc1-41f8-8116-460857d9bb6a', '～場合[ばあい]は', '~인 경우에는', '文[ぶん]/名詞[めいし] + の + 場合[ばあい]は', 4, 4, TRUE);
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('d5dd8a59-fbc1-41f8-8116-460857d9bb6a', '遅[おく]れる場合[ばあい]は連絡[れんらく]して。', '늦을 경우 연락해.', 'If you''re late, contact me.');
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('d5dd8a59-fbc1-41f8-8116-460857d9bb6a', '行[い]けない場合[ばあい]は教[おし]えて。', '못 갈 경우 알려줘.', 'If you can''t go, let me know.');
INSERT INTO grammar (id, pattern, meaning, connection, jlpt_level, conversation_level, is_core) VALUES ('11a2224b-3961-46d2-acc3-f63c7deb62b4', '～気[き]がする', '~인 느낌이 든다', '文[ぶん] + 気[き]がする', 4, 5, TRUE);
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('11a2224b-3961-46d2-acc3-f63c7deb62b4', '雨[あめ]が降[ふ]りそうな気[き]がする。', '비 올 것 같은 느낌이 들어.', 'I feel like it might rain.');
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('11a2224b-3961-46d2-acc3-f63c7deb62b4', 'なんか変[へん]な気[き]がする。', '뭔가 이상한 느낌이 들어.', 'I have a weird feeling.');
INSERT INTO grammar (id, pattern, meaning, connection, jlpt_level, conversation_level, is_core) VALUES ('1a9ac4f2-5ab4-4776-a146-bc320ffb72f5', '～理由[りゆう]は', '~이유는', '文[ぶん] + 理由[りゆう]は', 4, 4, FALSE);
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('1a9ac4f2-5ab4-4776-a146-bc320ffb72f5', '来[こ]ない理由[りゆう]は時間[じかん]がないから。', '안 오는 이유는 시간이 없어서야.', 'The reason I''m not coming is I have no time.');
INSERT INTO grammar_examples (grammar_id, japanese, korean, english) VALUES ('1a9ac4f2-5ab4-4776-a146-bc320ffb72f5', '理由[りゆう]は簡単[かんたん]だ。', '이유는 간단해.', 'The reason is simple.');
